      S.push([380, () => setTb({ lit: 0, note: "skip the first digit" })]);
      for (let i = 0; i < z; i++) {
        const v = i + 1;
        S.push([520, () => setTb((t) => ({ ...t, lit: v }))]);
      }
      S.push([520, () => setTb((t) => ({ ...t, row: { digits: "", pointAt: z, filled: [] }, note: "only the zeros count" }))]);
